package com.zoro.zoromart.dto;
/** Immutable order confirmation DTO created through its builder. */
public class OrderResponseDTO {private final long orderId;private final String paymentStatus;private final String message;private OrderResponseDTO(Builder b){orderId=b.orderId;paymentStatus=b.paymentStatus;message=b.message;}public long getOrderId(){return orderId;}public String getPaymentStatus(){return paymentStatus;}public String getMessage(){return message;}public static Builder builder(){return new Builder();}public static class Builder{private long orderId;private String paymentStatus="MOCK_CONFIRMED";private String message="Order placed";public Builder orderId(long id){orderId=id;return this;}public Builder paymentStatus(String status){paymentStatus=status;return this;}public Builder message(String text){message=text;return this;}public OrderResponseDTO build(){return new OrderResponseDTO(this);}}}
